import{_ as s,a0 as r,w as a,s as i,I as o,x as e,a1 as n,A as p,ao as C}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"如何在 CentOS 上啓用 軟件集 Software Collections（SCL） | LCTT x X-CMD","titleTemplate":false,"description":"如何在 CentOS 上啓用 軟件集 Software Collections（SCL） | LCTT (201512) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 CentOS 上啓用 軟件集 Software Collections（SCL） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 CentOS 上啓用 軟件集 Software Collections（SCL） | LCTT (201512) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201512/20151215 How to enable Software Collections (SCL) on CentOS","title":"如何在 CentOS 上啓用 軟件集 Software Collections（SCL）","tag":"201512","desc":""},"relativePath":"201512/20151215 How to enable Software Collections (SCL) on CentOS.md","filePath":"[post].md"}'),d={name:"201512/20151215 How to enable Software Collections (SCL) on CentOS.md"};function S(u,t,L,f,c,m){const l=r("Link");return a(),i("div",null,[t[17]||(t[17]=o("h1",{id:"如何在-centos-上啓用-軟件集-software-collections-scl",tabindex:"-1"},[e("如何在 CentOS 上啓用 軟件集 Software Collections（SCL） "),o("a",{class:"header-anchor",href:"#如何在-centos-上啓用-軟件集-software-collections-scl","aria-label":"Permalink to “如何在 CentOS 上啓用 軟件集 Software Collections（SCL）”"},"​")],-1)),t[18]||(t[18]=o("p",null,"紅帽企業版 linux（RHEL）和它的社區版分支——CentOS，提供10年的生命週期，這意味着 RHEL/CentOS 的每個版本會提供長達10年的安全更新。雖然這麼長的生命週期為企業用户提供了迫切需要的系統兼容性和可靠性，但也存在一個缺點：隨着底層的 RHEL/CentOS 版本接近生命週期的結束，核心應用和運行時環境變得陳舊過時。例如 CentOS 6.5，它的生命週期結束時間是2020年11月30日，其所攜帶的 Python 2.6.6和 MySQL 5.1.73，以今天的標準來看已經非常古老了。",-1)),t[19]||(t[19]=o("p",null,"另一方面，在 RHEL/CentOS 上試圖手動升級開發工具鏈和運行時環境存在使系統崩潰的潛在可能，除非所有依賴都被正確解決。通常情況下，手動升級都是不推薦的，除非你知道你在幹什麼。",-1)),o("p",null,[n(l,{href:"https://www.softwarecollections.org/"},{default:p(()=>[...t[0]||(t[0]=[e("軟件集（Software Collections）",-1)])]),_:1}),t[1]||(t[1]=e("（SCL）源出現了，以幫助解決 RHEL/CentOS 下的這種問題。SCL 的創建就是為了給 RHEL/CentOS 用户提供一種以方便、安全地安裝和使用應用程序和運行時環境的多個（而且可能是更新的）版本的方式，同時避免把系統搞亂。與之相對的是第三方源，它們可能會在已安裝的包之間引起衝突。",-1))]),t[20]||(t[20]=C(`<p>最新的 SCL 提供了：</p><ul><li>Python 3.3 和 2.7</li><li>PHP 5.4</li><li>Node.js 0.10</li><li>Ruby 1.9.3</li><li>Perl 5.16.3</li><li>MariaDB 和 MySQL 5.5</li><li>Apache httpd 2.4.6</li></ul><p>在這篇教程的剩餘部分，我會展示一下如何配置 SCL 源，以及如何安裝和啓用 SCL 中的包。</p><h3 id="配置-scl-源" tabindex="-1">配置 SCL 源 <a class="header-anchor" href="#配置-scl-源" aria-label="Permalink to “配置 SCL 源”">​</a></h3><p>SCL 可用於 CentOS 6.5 及更新的版本。要配置 SCL 源，只需執行：</p><pre><code>$ sudo yum install centos-release-SCL
</code></pre><p>要啓用和運行 SCL 中的應用，你還需要安裝下列包：</p><pre><code>$ sudo yum install scl-utils-build
</code></pre><p>執行下面的命令可以查看 SCL 中可用包的完整列表：</p><pre><code>$ yum --disablerepo=&quot;*&quot; --enablerepo=&quot;scl&quot; list available
</code></pre><p><img src="https://c2.staticflickr.com/6/5730/23304424250_f5c8a09584_c.jpg" alt=""></p><h3 id="從-scl-中安裝和啓用包" tabindex="-1">從 SCL 中安裝和啓用包 <a class="header-anchor" href="#從-scl-中安裝和啓用包" aria-label="Permalink to “從 SCL 中安裝和啓用包”">​</a></h3><p>既然你已配置好了 SCL，你可以繼續並從 SCL 中安裝包了。</p><p>你可以搜索 SCL 中的包：</p><pre><code>$ yum --disablerepo=&quot;*&quot; --enablerepo=&quot;scl&quot; search &lt;keyword&gt;
</code></pre><p>我們假設你要安裝 Python 3.3。</p><p>繼續，就像通常安裝包那樣使用 yum 安裝：</p><pre><code>$ sudo yum install python33
</code></pre><p>任何時候你都可以查看從 SCL 中安裝的包的列表，只需執行：</p><pre><code>$ scl --list

python33
</code></pre><p>SCL 的優點之一是安裝其中的包不會覆蓋任何系統文件，並且保證不會引起與系統中其它庫和應用的衝突。</p><p>例如，如果在安裝 python33 包後檢查默認的 python 版本，你會發現默認的版本並沒有改變：</p><pre><code>$ python --version

Python 2.6.6
</code></pre><p>如果想使用一個已經安裝的 SCL 包，你需要在每個命令中使用 <code>scl</code> 命令顯式啓用它（LCTT 譯註：即想在哪條命令中使用 SCL 中的包，就得通過<code>scl</code>命令執行該命令）</p><pre><code>$ scl enable &lt;scl-package-name&gt; &lt;command&gt;
</code></pre><p>例如，要針對<code>python</code>命令啓用 python33 包：</p><pre><code>$ scl enable python33 &#39;python --version&#39;

Python 3.3.2
</code></pre><p>如果想在啓用 python33 包時執行多條命令，你可以像下面那樣創建一個啓用 SCL 的 bash 會話：</p><pre><code>$ scl enable python33 bash
</code></pre><p>在這個 bash 會話中，默認的 python 會被切換為3.3版本，直到你輸入<code>exit</code>，退出會話。</p><p><img src="https://c2.staticflickr.com/6/5642/23491549632_1d08e163cc_c.jpg" alt=""></p><p>簡而言之，SCL 有幾分像 Python 的虛擬環境，但更通用，因為你可以為遠比 Python 更多的應用啓用/禁用 SCL 會話。</p>`,32)),o("p",null,[t[3]||(t[3]=e("更詳細的 SCL 指南，參考官方的",-1)),n(l,{href:"https://www.softwarecollections.org/docs/"},{default:p(()=>[...t[2]||(t[2]=[e("快速入門指南",-1)])]),_:1})]),t[21]||(t[21]=o("hr",null,null,-1)),o("p",null,[t[5]||(t[5]=e("via: ",-1)),n(l,{href:"http://xmodulo.com/enable-software-collections-centos.html"},{default:p(()=>[...t[4]||(t[4]=[e("http://xmodulo.com/enable-software-collections-centos.html",-1)])]),_:1})]),o("p",null,[t[9]||(t[9]=e("作者：",-1)),n(l,{href:"http://xmodulo.com/author/nanni"},{default:p(()=>[...t[6]||(t[6]=[e("Dan Nanni",-1)])]),_:1}),t[10]||(t[10]=e(" 譯者：",-1)),n(l,{href:"https://github.com/bianjp"},{default:p(()=>[...t[7]||(t[7]=[e("bianjp",-1)])]),_:1}),t[11]||(t[11]=e(" 校對：",-1)),n(l,{href:"https://github.com/wxy"},{default:p(()=>[...t[8]||(t[8]=[e("wxy",-1)])]),_:1})]),o("p",null,[t[14]||(t[14]=e("本文由 ",-1)),n(l,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[12]||(t[12]=[e("LCTT",-1)])]),_:1}),t[15]||(t[15]=e(" 原創編譯，",-1)),n(l,{href:"https://linux.cn/"},{default:p(()=>[...t[13]||(t[13]=[e("Linux中國",-1)])]),_:1}),t[16]||(t[16]=e(" 榮譽推出",-1))])])}const h=s(d,[["render",S]]);export{b as __pageData,h as default};
